steps.script:
const libs = (await __ss.api('GET', 'SmartSearch/Libraries')).body;
const movies = libs.find(l => l.Name === 'Movies').Id, movies2 = libs.find(l => l.Name === 'Movies 2').Id;
const users = (await __ss.api('GET', 'Users')).body;
const v2 = users.find(u => u.Name === 'viewer2');
const folders = (await __ss.api('GET', 'Library/MediaFolders')).body.Items.filter(f => f.Name !== 'Movies 2').map(f => f.Id);
const policy = Object.assign({}, v2.Policy, { EnableAllFolders: false, EnabledFolders: folders });
const p = await __ss.api('POST', 'Users/' + v2.Id + '/Policy', policy);
const removed = await __ss.cleanup('WC ');
const query = (libraries) => ({ Version: 1, Scope: { ItemKinds: ['Movie'], LibraryIds: libraries, IncludeMissing: false }, Where: { Match: 'All', Children: [] }, Sort: [{ Key: 'SortName', Order: 'Ascending' }] });
const a = await __ss.api('POST', 'SmartSearch/Queries', { Name: 'WC Two libraries', Description: 'Every movie of two libraries', Shared: true, Query: query([movies, movies2]) });
const b = await __ss.api('POST', 'SmartSearch/Queries', { Name: 'WC <img src=x onerror=\"window.__pwned=1\">\u202Eevil\u0007 \u05E9\u05DC\u05D5\u05DD', Description: '<b>not bold</b>', Shared: true, Query: query([movies]) });
return { policy: p.status, removed, a: a.status, b: b.status, twoId: a.body.Id, evilId: b.body.Id, movies, movies2, evilName: b.body.Name };
